static int budget_correct(Node from,Node to,int base){BudgetResidualFeatures r(from,to,base);double value=0.;
value+=budget_tree_0(r);
value+=budget_tree_1(r);
value+=budget_tree_2(r);
value+=budget_tree_3(r);
value+=budget_tree_4(r);
value+=budget_tree_5(r);
value+=budget_tree_6(r);
value+=budget_tree_7(r);
return int(std::nearbyint(std::max(0.,double(base)+value)));}
